import { Mesh, PlaneGeometry, MeshBasicNodeMaterial, DoubleSide } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Object} scenePlacement
 * @property {Array<number>} scenePlacement.position
 * @property {Array<number>} scenePlacement.rotation
 * @property {Array<number>} scenePlacement.scale
 * @property {Object} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {{ load: (url: string) => import('three').Texture }} textureLoader
 * @property {{ [key: string]: (obj: THREE.Object3D, params: any) => void }} primitives
 */

/**
 * Creates a textured plane node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  // Load texture synchronously via the provided loader
  const texture = ctx.textureLoader.load(config.assets.imageUrl);

  // Create material using NodeMaterial system
  const material = new MeshBasicNodeMaterial({
    map: texture,
    side: DoubleSide,
    transparent: true,
  });

  // Simple plane geometry; size will be controlled by object scale
  const geometry = new PlaneGeometry(1, 1);

  // Assemble mesh
  const mesh = new Mesh(geometry, material);

  // Apply placement transforms
  const [px, py, pz] = config.scenePlacement.position || [0, 0, 0];
  const [rx, ry, rz] = config.scenePlacement.rotation || [0, 0, 0];
  const [sx, sy, sz] = config.scenePlacement.scale || [1, 1, 1];

  mesh.position.set(px, py, pz);
  mesh.rotation.set(rx, ry, rz);
  mesh.scale.set(sx, sy, sz);

  // Prepare userData structure
  mesh.userData = {
    handlers: {},
    /** @type {() => void} */
    cleanup: () => {
      // Dispose of three.js resources
      geometry.dispose();
      material.dispose();
      if (texture) {
        texture.dispose();
      }
      // Kill any GSAP timelines that might have been created (none in this node)
      gsap.globalTimeline.clear();
    },
  };

  // No cinematic primitives to apply for this node

  return mesh;
}
